select case when customers.credit_limit >= 17800 then 'high' when customers.credit_limit >= 4400 then 'mid' else 'low' end as credit_limit_bucket, concat_ws(', ', sort_array(collect_set(sessions.country))) as country_values from sessions inner join customers on sessions.customer_id = customers.id group by case when customers.credit_limit >= 17800 then 'high' when customers.credit_limit >= 4400 then 'mid' else 'low' end order by credit_limit_bucket desc
